import React, { useState, useEffect, useRef, useCallback } from 'react';
import './ChatInterface.css';

const ChatInterface = ({ user, socket, onLogout }) => {
  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [sessionId] = useState(() => `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`);
  const [isListening, setIsListening] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [recognition, setRecognition] = useState(null);
  const [synthesis, setSynthesis] = useState(null);
  const [isVoiceEnabled, setIsVoiceEnabled] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [savedSessions, setSavedSessions] = useState([]);
  const [currentSession, setCurrentSession] = useState(null);
  const [sentiment, setSentiment] = useState(null);

  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    // Initialize Web Speech API
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      const recognitionInstance = new SpeechRecognition();
      recognitionInstance.continuous = false;
      recognitionInstance.interimResults = false;
      recognitionInstance.lang = 'en-US';

      recognitionInstance.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        const confidence = event.results[0][0].confidence;
        setInputValue(transcript);
        setIsListening(false);

        // Analyze sentiment of voice input
        analyzeSentiment(transcript);

        // Show confidence feedback
        if (confidence < 0.5) {
          addMessage('system', `Voice detected with low confidence (${Math.round(confidence * 100)}%). Please verify the text.`);
        }
      };

      recognitionInstance.onerror = (event) => {
        console.error('Speech recognition error:', event.error);
        setIsListening(false);

        // Provide user-friendly error messages
        let errorMessage = 'Voice recognition error: ';
        switch(event.error) {
          case 'no-speech':
            errorMessage += 'No speech detected. Please try again.';
            break;
          case 'audio-capture':
            errorMessage += 'Microphone not accessible. Please check permissions.';
            break;
          case 'not-allowed':
            errorMessage += 'Microphone permission denied. Please enable it in browser settings.';
            break;
          case 'network':
            errorMessage += 'Network error. Please check your connection.';
            break;
          default:
            errorMessage += event.error;
        }
        addMessage('error', errorMessage);
      };

      recognitionInstance.onend = () => {
        setIsListening(false);
      };

      setRecognition(recognitionInstance);
    }

    if ('speechSynthesis' in window) {
      setSynthesis(window.speechSynthesis);
    }

    // Add welcome message
    addMessage('system', `Welcome to Voxa CLI, ${user.username}! Type 'help' for available commands.`);

    // Load chat history
    loadChatHistory();

    return () => {
      if (recognition) {
        recognition.stop();
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user.username]);

  useEffect(() => {
    if (socket) {
      socket.on('chat_message', handleIncomingMessage);
      socket.on('error', handleSocketError);

      return () => {
        socket.off('chat_message');
        socket.off('error');
      };
    }
  }, [socket, handleIncomingMessage, handleSocketError]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, scrollToBottom]);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  const addMessage = useCallback((type, content, timestamp = new Date()) => {
    const message = {
      id: Date.now() + Math.random(),
      type,
      content,
      timestamp: timestamp.toISOString()
    };
    setMessages(prev => [...prev, message]);
    return message;
  }, []);

  const analyzeSentiment = useCallback((text) => {
    // Simple sentiment analysis based on keywords
    const positiveWords = ['good', 'great', 'excellent', 'happy', 'love', 'wonderful', 'amazing', 'fantastic', 'perfect', 'best'];
    const negativeWords = ['bad', 'terrible', 'awful', 'hate', 'worst', 'horrible', 'poor', 'sad', 'angry', 'frustrated'];

    const lowerText = text.toLowerCase();
    const positiveCount = positiveWords.filter(word => lowerText.includes(word)).length;
    const negativeCount = negativeWords.filter(word => lowerText.includes(word)).length;

    let sentimentResult = 'neutral';
    if (positiveCount > negativeCount) {
      sentimentResult = 'positive';
    } else if (negativeCount > positiveCount) {
      sentimentResult = 'negative';
    }

    setSentiment(sentimentResult);
    return sentimentResult;
  }, []);

  const handleIncomingMessage = useCallback((data) => {
    setIsTyping(false);
    addMessage(data.type, data.content, new Date(data.timestamp));

    // Speak bot responses if voice is enabled
    if (data.type === 'bot' && isVoiceEnabled && synthesis) {
      try {
        const utterance = new SpeechSynthesisUtterance(data.content);
        utterance.rate = 0.9;
        utterance.pitch = 1;
        utterance.volume = 1;

        // Add error handling for speech synthesis
        utterance.onerror = (event) => {
          console.error('Speech synthesis error:', event);
          addMessage('error', 'Voice output failed. Please check your audio settings.');
        };

        synthesis.speak(utterance);
      } catch (error) {
        console.error('Speech synthesis error:', error);
      }
    }
  }, [addMessage, isVoiceEnabled, synthesis]);

  const handleSocketError = useCallback((data) => {
    addMessage('error', data.message);
  }, [addMessage]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!inputValue.trim() || !socket) return;

    const message = inputValue.trim();
    setInputValue('');

    // Analyze sentiment of user input
    const userSentiment = analyzeSentiment(message);

    // Handle special commands
    if (message.toLowerCase() === 'help') {
      showHelp();
      return;
    }

    if (message.toLowerCase() === 'clear') {
      setMessages([]);
      addMessage('system', 'Terminal cleared.');
      return;
    }

    if (message.toLowerCase() === 'save_session') {
      saveCurrentSession();
      return;
    }

    if (message.toLowerCase() === 'history') {
      setShowHistory(!showHistory);
      addMessage('system', `Chat history ${showHistory ? 'hidden' : 'shown'}.`);
      return;
    }

    if (message.toLowerCase() === 'voice_toggle') {
      setIsVoiceEnabled(!isVoiceEnabled);
      addMessage('system', `Voice output ${isVoiceEnabled ? 'disabled' : 'enabled'}.`);
      return;
    }

    if (message.toLowerCase() === 'sentiment') {
      addMessage('system', `Current sentiment: ${sentiment || 'neutral'}`);
      return;
    }

    // Show typing indicator
    setIsTyping(true);

    // Send message to server with sentiment
    socket.emit('chat_message', {
      message: message,
      session_id: sessionId,
      sentiment: userSentiment
    });
  };

  const showHelp = () => {
    const helpText = `
Available Commands:
• help - Show this help message
• clear - Clear the terminal
• save_session - Save current chat session
• history - Show/hide chat history
• voice_toggle - Enable/disable voice output
• weather [location] - Get weather information
• search [query] - Search the web
• calculate [expression] - Perform calculations
• time - Get current time

Examples:
• "What's the weather in London?"
• "Search for latest AI news"
• "Calculate 5 plus 3"
• "What time is it?"
    `;
    addMessage('system', helpText);
  };

  const startListening = () => {
    if (!recognition) {
      addMessage('error', 'Voice recognition is not supported in your browser. Please use Chrome, Edge, or Safari.');
      return;
    }

    if (!isListening) {
      try {
        setIsListening(true);
        recognition.start();
        addMessage('system', 'Listening... Speak now.');
      } catch (error) {
        console.error('Error starting voice recognition:', error);
        setIsListening(false);
        addMessage('error', 'Failed to start voice recognition. Please try again.');
      }
    }
  };

  const stopListening = () => {
    if (recognition && isListening) {
      try {
        recognition.stop();
        setIsListening(false);
        addMessage('system', 'Voice input stopped.');
      } catch (error) {
        console.error('Error stopping voice recognition:', error);
        setIsListening(false);
      }
    }
  };

  const loadChatHistory = async () => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await fetch('/api/history/list', {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setSavedSessions(data.sessions);
      }
    } catch (error) {
      console.error('Error loading chat history:', error);
    }
  };

  const saveCurrentSession = async () => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await fetch('/api/history/save', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          session_id: sessionId,
          title: `Chat Session ${new Date().toLocaleString()}`,
          messages: messages.map(msg => ({
            type: msg.type,
            content: msg.content,
            timestamp: msg.timestamp
          }))
        })
      });

      if (response.ok) {
        addMessage('system', 'Chat session saved successfully!');
        loadChatHistory();
      } else {
        addMessage('error', 'Failed to save chat session');
      }
    } catch (error) {
      addMessage('error', 'Error saving chat session');
    }
  };

  const loadSession = async (sessionId) => {
    try {
      const token = localStorage.getItem('access_token');
      const response = await fetch(`/api/history/${sessionId}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setMessages(data.session.messages.map(msg => ({
          id: msg.id,
          type: msg.type,
          content: msg.content,
          timestamp: msg.timestamp
        })));
        setCurrentSession(data.session);
        setShowHistory(false);
        addMessage('system', `Loaded session: ${data.session.title}`);
      }
    } catch (error) {
      addMessage('error', 'Error loading chat session');
    }
  };

  const formatTimestamp = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString();
  };

  const renderPrompt = () => (
    <div className="command-prompt">
      <span className="prompt-user">{user.username}</span>
      <span className="prompt-host">@voxa-cli</span>
      <span className="prompt-path">:~$</span>
    </div>
  );

  return (
    <div className="chat-interface">
      <div className="terminal-window">
        <div className="terminal-header">
          <div className="terminal-title">Voxa CLI Terminal</div>
          <div className="terminal-controls">
            <div className="terminal-control close"></div>
            <div className="terminal-control minimize"></div>
            <div className="terminal-control maximize"></div>
          </div>
        </div>

        <div className="terminal-body">
          {messages.map((message) => (
            <div key={message.id} className={`message ${message.type}`}>
              {message.type === 'user' && renderPrompt()}
              <div className="message-content terminal-text">
                {message.content}
              </div>
              <div className="message-timestamp">
                {formatTimestamp(message.timestamp)}
              </div>
            </div>
          ))}

          {isTyping && (
            <div className="message bot">
              <div className="typing-indicator">
                <span>Voxa is typing</span>
                <span className="cursor">_</span>
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        <form className="input-container" onSubmit={handleSubmit}>
          {renderPrompt()}
          <input
            ref={inputRef}
            type="text"
            className="input-field terminal-text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder="Type your command or question..."
            autoFocus
          />

          <div className="input-controls">
            <button
              type="button"
              className={`btn voice-btn ${isListening ? 'listening' : ''}`}
              onClick={isListening ? stopListening : startListening}
              title={isListening ? 'Stop listening' : 'Start voice input'}
            >
              🎤
            </button>

            <button
              type="button"
              className="btn history-btn"
              onClick={() => setShowHistory(!showHistory)}
              title="Chat history"
            >
              📚
            </button>

            <button
              type="button"
              className="btn voice-toggle-btn"
              onClick={() => setIsVoiceEnabled(!isVoiceEnabled)}
              title={`Voice output ${isVoiceEnabled ? 'enabled' : 'disabled'}`}
            >
              {isVoiceEnabled ? '🔊' : '🔇'}
            </button>
          </div>
        </form>
      </div>

      {showHistory && (
        <div className="history-panel">
          <div className="history-header">
            <h3>Chat History</h3>
            <button
              className="btn close-btn"
              onClick={() => setShowHistory(false)}
            >
              ✕
            </button>
          </div>

          <div className="history-list">
            {savedSessions.map((session) => (
              <div
                key={session.id}
                className={`history-item ${currentSession?.id === session.id ? 'active' : ''}`}
                onClick={() => loadSession(session.session_id)}
              >
                <div className="history-title">{session.title}</div>
                <div className="history-meta">
                  {new Date(session.updated_at).toLocaleDateString()} - {session.message_count} messages
                </div>
              </div>
            ))}

            {savedSessions.length === 0 && (
              <div className="no-history">
                No saved chat sessions yet.
              </div>
            )}
          </div>
        </div>
      )}

      <div className="user-menu">
        <div className="user-info">
          <span className="username">{user.username}</span>
          <div className="user-color-preview" style={{ backgroundColor: user.terminal_color }}></div>
        </div>
        <button className="btn logout-btn" onClick={onLogout}>
          Logout
        </button>
      </div>
    </div>
  );
};

export default ChatInterface;
